//! Compares the xtce-rs TM decoding and TC encoding with the results produced by Yamcs.
//!
//! The cases are in tests/golden/cases.txt; tests/golden/expected.txt is generated by running them through Yamcs
//! with tools/yamcs-golden/generate.sh (see the comments in that file for the format).
//!
//! For TM, the extracted parameters (in order) with their raw and engineering values including the Yamcs
//! value types and the validity are compared. The algorithms are not run by the Yamcs extractor so their outputs
//! are not compared.
//! For TC, the binary and the raw and engineering values of all arguments are compared (the types of the raw
//! values are not compared because Yamcs uses for the arguments different raw types than for the parameters).
//! In case of errors, only the fact that an error is produced is compared, not the message.

use std::{
    collections::HashMap,
    fmt::Write,
    path::Path,
};

use xtce_rs::{
    mdb::{
        types::{DataEncoding, TypeData},
        DataTypeIdx, MissionDatabase, NamedItem,
    },
    parser,
    proc::containers::process,
    tc::encode_command,
    value::{Value, ValueType},
};

struct Case {
    header: Vec<String>,
    lines: Vec<String>,
}

fn read_cases() -> Vec<Case> {
    let text = std::fs::read_to_string("tests/golden/expected.txt").unwrap();
    let mut cases: Vec<Case> = Vec::new();
    for line in text.lines() {
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        if line.starts_with("tm\t") || line.starts_with("tc\t") {
            cases.push(Case { header: line.split('\t').map(|s| s.to_owned()).collect(), lines: Vec::new() });
        } else {
            cases.last_mut().expect("line before the first case").lines.push(line.to_owned());
        }
    }
    cases
}

/// formats a double like the Java Double.toString (or Float.toString if `float` is true)
fn java_float(x: f64, float: bool) -> String {
    if float {
        xtce_rs::format::java_float(x as f32)
    } else {
        xtce_rs::format::java_double(x)
    }
}

fn type_name(vt: ValueType) -> &'static str {
    match vt {
        ValueType::Sint32 => "SINT32",
        ValueType::Uint32 => "UINT32",
        ValueType::Sint64 => "SINT64",
        ValueType::Uint64 => "UINT64",
        ValueType::Float => "FLOAT",
        ValueType::Double => "DOUBLE",
        ValueType::Boolean => "BOOLEAN",
        ValueType::String => "STRING",
        ValueType::Binary => "BINARY",
        ValueType::Enumerated => "ENUMERATED",
        ValueType::Timestamp => "TIMESTAMP",
        ValueType::Aggregate => "AGGREGATE",
        ValueType::Array => "ARRAY",
    }
}

/// formats the value in the same way as the Golden.java (TYPE:value)
fn format(mdb: &MissionDatabase, dtidx: DataTypeIdx, v: &Value, raw: bool) -> String {
    let dt = mdb.get_data_type(dtidx);
    let vt = if raw { dt.encoding.raw_value_type() } else { None }.unwrap_or_else(|| dt.eng_value_type());
    let s = match (vt, v) {
        (_, Value::Aggregate(av)) => {
            let TypeData::Aggregate(at) = &dt.type_data else { return format!("{:?}", v) };
            let l: Vec<String> = at
                .members
                .iter()
                .map(|m| {
                    let mv = match av.0.get(&m.name()) {
                        Some(mv) => format(mdb, m.dtype, mv, raw),
                        None => "-".into(),
                    };
                    format!("{}={}", mdb.name2str(m.name()), mv)
                })
                .collect();
            return format!("AGGREGATE:{{{}}}", l.join(","));
        }
        (_, Value::Array(av)) => {
            let TypeData::Array(at) = &dt.type_data else { return format!("{:?}", v) };
            let l: Vec<String> = av.values.iter().map(|x| format(mdb, at.dtype, x, raw)).collect();
            let dims: Vec<String> = av.dims.iter().map(|d| d.to_string()).collect();
            return format!("ARRAY[{}]:[{}]", dims.join(","), l.join(","));
        }
        (ValueType::Float, Value::Double(x)) => java_float(*x, true),
        (ValueType::Double, Value::Double(x)) => java_float(*x, false),
        (ValueType::Sint32 | ValueType::Sint64 | ValueType::Uint32 | ValueType::Uint64, Value::Int64(x)) => {
            x.to_string()
        }
        (ValueType::Sint32 | ValueType::Sint64 | ValueType::Uint32 | ValueType::Uint64, Value::Uint64(x)) => {
            x.to_string()
        }
        (ValueType::Boolean, Value::Boolean(b)) => b.to_string(),
        (ValueType::String, Value::StringValue(s)) => hex::encode(s.as_bytes()),
        (ValueType::Binary, Value::Binary(b)) => hex::encode(b.as_slice()),
        (ValueType::Timestamp, Value::Timestamp(t)) => t.to_string(),
        (ValueType::Enumerated, Value::Enumerated(ev)) => format!("{}:{}", ev.key, ev.value),
        // the value does not match the type
        _ => return format!("{}:{:?}", type_name(vt), v),
    };
    format!("{}:{}", type_name(vt), s)
}

/// Yamcs keeps the raw values of the command arguments with signed integer encodings masked to the size of the
/// encoding (e.g. -2 encoded on 16 bits is 65534)
fn yamcs_tc_raw(mdb: &MissionDatabase, dtidx: DataTypeIdx, v: &Value) -> Value {
    let dt = mdb.get_data_type(dtidx);
    match (&dt.type_data, v) {
        (TypeData::Aggregate(at), Value::Aggregate(av)) => {
            let mut av = av.clone();
            for m in &at.members {
                if let Some(mv) = av.0.get_mut(&m.name()) {
                    *mv = yamcs_tc_raw(mdb, m.dtype, mv);
                }
            }
            Value::Aggregate(av)
        }
        (TypeData::Array(at), Value::Array(av)) => {
            let mut av = av.clone();
            av.values = av.values.iter().map(|x| yamcs_tc_raw(mdb, at.dtype, x)).collect();
            Value::Array(av)
        }
        // the values up to 32 bits are Java int: the cast restores the sign for 32 bits
        (_, Value::Int64(x)) if *x < 0 => match &dt.encoding {
            DataEncoding::Integer(ide) if ide.size_in_bits < 64 && ide.size_in_bits != 32 => {
                Value::Uint64((*x as u64) & (u64::MAX >> (64 - ide.size_in_bits)))
            }
            _ => v.clone(),
        },
        _ => v.clone(),
    }
}

/// removes the type names from a formatted value
fn strip_types(s: &str) -> String {
    let mut r = String::new();
    let mut rest = s;
    while !rest.is_empty() {
        // a type name is a sequence of uppercase letters and digits, optionally followed by [dims], followed by ':'
        let n = rest.chars().take_while(|c| c.is_ascii_uppercase() || c.is_ascii_digit()).count();
        let mut m = n;
        if n > 0 && rest[n..].starts_with('[') {
            if let Some(k) = rest[n..].find(']') {
                m = n + k + 1;
            }
        }
        let at_start = r.is_empty() || r.ends_with(['{', '[', ',', '=']);
        if n > 0 && at_start && rest[m..].starts_with(':') && rest.as_bytes()[0].is_ascii_uppercase() {
            rest = &rest[m + 1..];
            continue;
        }
        let c = rest.chars().next().unwrap();
        r.push(c);
        rest = &rest[c.len_utf8()..];
    }
    r
}

fn normalize_tc_line(line: &str) -> String {
    if !line.starts_with("arg\t") {
        return line.to_owned();
    }
    line.split('\t')
        .map(|f| match f.strip_prefix("raw=") {
            Some(v) => format!("raw={}", strip_types(v)),
            None => f.to_owned(),
        })
        .collect::<Vec<_>>()
        .join("\t")
}

fn run_tm(mdb: &MissionDatabase, header: &[String], expected: &[String]) -> Vec<String> {
    let root = mdb.search_container(&header[2]).unwrap_or_else(|| panic!("no container {}", header[2]));
    let packet = hex::decode(&header[3]).unwrap();
    let expect_error = expected.iter().any(|l| l.starts_with("error\t"));
    match process(mdb, &packet, root) {
        Err(e) => {
            if expect_error {
                expected.to_vec()
            } else {
                vec![format!("rust error\t{:?}", e)]
            }
        }
        Ok(r) => {
            let mut lines = Vec::new();
            // the Yamcs container extractor does not run the algorithms
            let tm = r.iter().filter(|pv| pv.raw_value.is_some());
            for (i, pv) in tm.enumerate() {
                let p = mdb.get_parameter(pv.pidx);
                // use the qualified name from the expected line if it refers to the same parameter
                let qn = expected
                    .get(i)
                    .and_then(|l| l.split('\t').nth(1))
                    .filter(|qn| mdb.search_parameter(qn) == Some(pv.pidx))
                    .map(|s| s.to_owned())
                    .unwrap_or_else(|| format!("?{}", mdb.name2str(p.name())));
                let ptype = p.ptype.unwrap();
                let mut line = format!("param\t{}\traw=", qn);
                match &pv.raw_value {
                    Some(rv) => line.push_str(&format(mdb, ptype, rv, true)),
                    None => line.push('-'),
                }
                write!(line, "\teng={}", format(mdb, ptype, &pv.eng_value, false)).unwrap();
                if pv.status.is_invalid() {
                    line.push_str("\tinvalid");
                }
                lines.push(line);
            }
            if expect_error {
                lines.push("rust: no error".into());
            }
            lines
        }
    }
}

fn run_tc(mdb: &MissionDatabase, header: &[String], expected: &[String]) -> Vec<String> {
    let cmd = mdb.search_command(&header[2]).unwrap_or_else(|| panic!("no command {}", header[2]));
    let mut args = HashMap::new();
    for a in header.get(3).map(|s| s.as_str()).unwrap_or("").split(';') {
        let a = a.trim();
        if a.is_empty() {
            continue;
        }
        let (k, v) = a.split_once('=').unwrap();
        args.insert(k.trim().to_owned(), Value::StringValue(Box::new(v.trim().to_owned())));
    }
    let expect_error = expected.iter().any(|l| l.starts_with("error\t"));
    match encode_command(mdb, cmd, &args) {
        Err(e) => {
            if expect_error {
                expected.to_vec()
            } else {
                vec![format!("rust error\t{}", e)]
            }
        }
        Ok(r) => {
            let mut lines = vec![format!("binary\t{}", hex::encode(&r.binary))];
            let mut args = r.args.clone();
            args.sort_by(|a, b| mdb.name2str(a.name).cmp(mdb.name2str(b.name)));
            for a in args {
                lines.push(format!(
                    "arg\t{}\traw={}\teng={}",
                    mdb.name2str(a.name),
                    strip_types(&format(mdb, a.atype, &yamcs_tc_raw(mdb, a.atype, &a.raw_value), true)),
                    format(mdb, a.atype, &a.eng_value, false)
                ));
            }
            if expect_error {
                lines.push("rust: no error".into());
            }
            lines
        }
    }
}

#[test]
fn yamcs_golden() {
    let mut mdbs: HashMap<String, MissionDatabase> = HashMap::new();
    let cases = read_cases();
    assert!(!cases.is_empty());
    let mut failed = 0;
    for case in &cases {
        let file = &case.header[1];
        let mdb = mdbs.entry(file.clone()).or_insert_with(|| {
            parser::parse_files(&[Path::new(&format!("test-xtce-files/{}", file))]).unwrap()
        });
        let (expected, actual): (Vec<String>, Vec<String>) = if case.header[0] == "tm" {
            (case.lines.clone(), run_tm(mdb, &case.header, &case.lines))
        } else {
            let expected: Vec<String> = case.lines.iter().map(|l| normalize_tc_line(l)).collect();
            (expected.clone(), run_tc(mdb, &case.header, &expected))
        };
        if expected != actual {
            failed += 1;
            println!("\nMISMATCH {}", case.header.join(" | "));
            let n = expected.len().max(actual.len());
            for i in 0..n {
                let e = expected.get(i).map(|s| s.as_str()).unwrap_or("<none>");
                let a = actual.get(i).map(|s| s.as_str()).unwrap_or("<none>");
                if e == a {
                    println!("    {}", e);
                } else {
                    println!("  - {}\n  + {}", e, a);
                }
            }
        }
    }
    assert_eq!(0, failed, "{} out of {} golden cases differ from Yamcs", failed, cases.len());
}

#[test]
fn java_float_format() {
    assert_eq!("1.0", java_float(1.0, false));
    assert_eq!("0.1", java_float(0.1, false));
    assert_eq!("0.001", java_float(0.001, false));
    assert_eq!("1.0E-4", java_float(0.0001, false));
    assert_eq!("1234567.0", java_float(1234567.0, false));
    assert_eq!("1.0E7", java_float(1e7, false));
    assert_eq!("-1.25E10", java_float(-1.25e10, false));
    assert_eq!("0.3", java_float(0.3f32 as f64, true));
    assert_eq!("0.30000001192092896", java_float(0.3f32 as f64, false));
    assert_eq!("3.4028235E38", java_float(f32::MAX as f64, true));
}

#[test]
fn strip_type_names() {
    assert_eq!("5", strip_types("UINT32:5"));
    assert_eq!("5:STANDBY", strip_types("ENUMERATED:5:STANDBY"));
    assert_eq!("{x=2,y=-3}", strip_types("AGGREGATE:{x=SINT32:2,y=SINT32:-3}"));
    assert_eq!("[1,2]", strip_types("ARRAY[2]:[UINT32:1,UINT32:2]"));
}
